/* Shared chart grammar: truthful units, varied forms, hover/focus details. */
let vizSequence=0;
function vizAttrs(title,label,value,unit,extra={}){const info={title,label,value,unit,...extra};return `data-viz-point="${escapeHTML(JSON.stringify(info))}" tabindex="0" role="button" aria-label="${escapeHTML(label+': '+nfmt(value)+' '+unit)}" onclick="inspectVizPoint(this)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();inspectVizPoint(this)}"`}
pointAttrs=function(title,label,value,unit){return vizAttrs(title,label,value,unit)};
function inspectVizPoint(el){hideVizTooltip();const p=JSON.parse(el.getAttribute('data-viz-point'));chartPoint(p.title,p.label,p.value,p.unit)}
function chooseViz(title,options){if(options.viz)return options.viz;const t=title.toLowerCase();if(/downtime|lost production time/.test(t))return 'pareto';if(/cost of poor quality|cost contribution/.test(t))return 'waterfall';if(/compliance checks|regulatory compliance/.test(t))return 'heatmap';if(/warranty|claim counts|water withdrawal/.test(t))return 'lollipop';if(/batch status|maintenance completion|delivery status/.test(t))return 'donut';if(/utilization|effectiveness|supplier quality|quality by|defect rates/.test(t))return 'bullet';if(/energy consumption|production trend|factory output|carbon emissions|utility demand|resource efficiency/.test(t))return 'area';if(options.type==='bar')return 'column';return 'line'}
function chartShell(title,subtitle,unit,svg,type,options={}){const notes={area:'Operating trend',line:'Trend',column:'Category comparison',lollipop:'Ranked comparison',heatmap:'Target attainment',bullet:'Actual against target',waterfall:'Cost contributions · total at right',pareto:'Bars: duration · line: cumulative share'};return `<section class="panel analytics-panel varied-chart" data-viz-chart="chart-${++vizSequence}" data-chart-type="${type}"><div class="panelhead"><div><h2>${title}</h2><small>${subtitle}</small></div><span class="chart-unit">${unit}</span></div>${svg}<div class="chart-caption"><span>${notes[type]||'Composition'}${options.target!==undefined?' · target '+options.target+' '+unit:''}</span><span>Hover for details</span></div></section>`}
function numericSeries(values){return values.map(v=>Number.isFinite(Number(v))?Math.max(0,Number(v)):0)}
analyticsChart=function(title,subtitle,labels,rawValues,unit,options={}){const values=numericSeries(rawValues),type=chooseViz(title,options);if(type==='donut')return compositionChart(title,subtitle,labels,values,unit);if(type==='lollipop')return lollipopViz(title,subtitle,labels,values,unit,options);if(type==='waterfall')return waterfallViz(title,subtitle,labels,values,unit,options);if(type==='pareto')return paretoViz(title,subtitle,labels,values,unit,options);if(type==='heatmap')return heatmapViz(title,subtitle,labels,values,unit,options);if(type==='bullet')return bulletViz(title,subtitle,labels,values,unit,options);const id='fill-'+(++vizSequence),max=Math.max(...values,Number(options.target)||0)*1.18||1,left=52,right=525,top=28,bottom=173,x=i=>values.length===1?(left+right)/2:left+i*(right-left)/(values.length-1),y=v=>bottom-v/max*(bottom-top),grid=[0,.5,1].map(r=>`<line x1="${left}" x2="${right}" y1="${y(max*r)}" y2="${y(max*r)}" class="viz-grid"/><text x="${left-9}" y="${y(max*r)+4}" text-anchor="end">${nfmt(max*r)}</text>`).join(''),target=options.target!==undefined?`<g ${vizAttrs(title,'Target',options.target,unit,{note:'Reference value'})}><line x1="${left}" x2="${right}" y1="${y(options.target)}" y2="${y(options.target)}" class="viz-target"/><rect x="${left}" y="${y(options.target)-6}" width="${right-left}" height="12" fill="transparent"/><text x="${right}" y="${y(options.target)-7}" text-anchor="end" class="viz-target-text">Target ${options.target}</text></g>`:'',path=values.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');let plot='';if(type==='column'){const width=Math.min(40,(right-left)/Math.max(values.length,1)*.5);plot=values.map((v,i)=>`<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{target:options.target})}><rect x="${x(i)-width/2-5}" y="${Math.min(y(v),bottom-12)}" width="${width+10}" height="${Math.max(12,bottom-y(v))}" fill="transparent"/><rect x="${x(i)-width/2}" y="${y(v)}" width="${width}" height="${bottom-y(v)}" rx="4" fill="${palette[i%palette.length]}"/></g>`).join('')}else{plot=`${type==='area'?`<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${palette[0]}" stop-opacity=".36"/><stop offset="1" stop-color="${palette[0]}" stop-opacity=".02"/></linearGradient></defs><path d="${path} L${x(values.length-1)},${bottom} L${x(0)},${bottom} Z" fill="url(#${id})"/>`:''}<path d="${path}" fill="none" stroke="${palette[0]}" stroke-width="3"/>${values.map((v,i)=>`<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{target:options.target})}><line class="viz-crosshair" x1="${x(i)}" x2="${x(i)}" y1="${top}" y2="${bottom}"/><circle cx="${x(i)}" cy="${y(v)}" r="13" fill="transparent"/><circle class="viz-dot" cx="${x(i)}" cy="${y(v)}" r="4.5" fill="${palette[0]}"/></g>`).join('')}`};const svg=`<svg class="analytics-svg" viewBox="0 0 560 215" aria-label="${title} · ${unit}" data-viz-type="${type}">${grid}${target}${plot}${labels.map((l,i)=>`<text x="${x(i)}" y="199" text-anchor="middle">${escapeHTML(l)}</text>`).join('')}</svg>`;return chartShell(title,subtitle,unit,svg,type,options)};
function lollipopViz(title,subtitle,labels,values,unit,options){const rows=labels.map((l,i)=>({l,v:values[i]})).sort((a,b)=>b.v-a.v),max=Math.max(...values,Number(options.target)||0)*1.12||1,left=105,right=500,dy=145/Math.max(rows.length,1),sum=values.reduce((a,b)=>a+b,0);const svg=`<svg class="analytics-svg" viewBox="0 0 560 215" data-viz-type="lollipop" aria-label="${title}">${rows.map((r,i)=>{const y=36+i*dy,x=left+r.v/max*(right-left);return `<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,r.l,r.v,unit,{share:sum?r.v/sum*100:0})}><rect x="5" y="${y-13}" width="540" height="26" fill="transparent"/><text x="${left-13}" y="${y+4}" text-anchor="end">${escapeHTML(r.l)}</text><line x1="${left}" x2="${right}" y1="${y}" y2="${y}" class="viz-track"/><line x1="${left}" x2="${x}" y1="${y}" y2="${y}" stroke="${palette[i%palette.length]}" stroke-width="3"/><circle class="viz-dot" cx="${x}" cy="${y}" r="6" fill="${palette[i%palette.length]}"/><text x="${x+12}" y="${y+4}">${nfmt(r.v)}</text></g>`}).join('')}<text x="${left}" y="201">0</text><text x="${right}" y="201" text-anchor="end">${nfmt(max)} ${unit}</text></svg>`;return chartShell(title,subtitle,unit,svg,'lollipop',options)}
function bulletViz(title,subtitle,labels,values,unit,options){const target=options.target??(unit==='%'?95:undefined),max=Math.max(...values,Number(target)||0,unit==='%'&&Math.max(...values,Number(target)||0)>50?100:0)*1.04||1,left=106,right=505,dy=144/Math.max(values.length,1);const svg=`<svg class="analytics-svg" viewBox="0 0 560 215" data-viz-type="bullet" aria-label="${title}">${values.map((v,i)=>{const y=32+i*dy,x=left+v/max*(right-left),tx=left+(target||0)/max*(right-left);return `<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{target})}><rect x="5" y="${y-15}" width="540" height="30" fill="transparent"/><text x="${left-13}" y="${y+4}" text-anchor="end">${escapeHTML(labels[i])}</text><rect x="${left}" y="${y-7}" width="${right-left}" height="14" rx="5" fill="#ffffff16"/><rect x="${left}" y="${y-5}" width="${x-left}" height="10" rx="4" fill="${palette[i%palette.length]}"/>${target!==undefined?`<line x1="${tx}" x2="${tx}" y1="${y-12}" y2="${y+12}" class="viz-target-tick"/>`:''}<text x="${right+9}" y="${y+4}">${nfmt(v)}</text></g>`}).join('')}<text x="${left}" y="200">0</text><text x="${right}" y="200" text-anchor="end">${nfmt(max)} ${unit}</text>${target!==undefined?'<text x="275" y="200" text-anchor="middle">│ Target '+target+'</text>':''}</svg>`;return chartShell(title,subtitle,unit,svg,'bullet',{...options,target})}
function waterfallViz(title,subtitle,labels,values,unit,options){const total=values.reduce((a,b)=>a+b,0),max=total*1.2||1,bottom=172,top=28,step=470/(values.length+1),x=i=>60+i*step,y=v=>bottom-v/max*(bottom-top);let running=0;const marks=values.map((v,i)=>{const previous=running;running+=v;return `<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{share:total?v/total*100:0,note:'Running total: '+nfmt(running)+' '+unit})}><rect x="${x(i)-5}" y="${y(running)-6}" width="46" height="${Math.max(12,y(previous)-y(running)+10)}" fill="transparent"/><rect x="${x(i)}" y="${y(running)}" width="35" height="${Math.max(0,y(previous)-y(running))}" rx="3" fill="${palette[i%palette.length]}"/><line x1="${x(i)+35}" x2="${x(i+1)}" y1="${y(running)}" y2="${y(running)}" class="viz-waterfall-link"/><text x="${x(i)+17}" y="${y(running)-7}" text-anchor="middle">${nfmt(v)}</text></g>`}).join('');const svg=`<svg class="analytics-svg" viewBox="0 0 560 215" data-viz-type="waterfall" aria-label="${title}">${[0,.5,1].map(r=>`<line x1="48" x2="530" y1="${y(max*r)}" y2="${y(max*r)}" class="viz-grid"/><text x="39" y="${y(max*r)+4}" text-anchor="end">${nfmt(max*r)}</text>`).join('')}${marks}<g class="viz-mark" data-viz-index="total" ${vizAttrs(title,'Total',total,unit,{share:100})}><rect x="${x(values.length)}" y="${y(total)}" width="35" height="${bottom-y(total)}" rx="3" fill="#e9d8f4"/><text x="${x(values.length)+17}" y="${y(total)-7}" text-anchor="middle">${nfmt(total)}</text></g>${[...labels,'Total'].map((l,i)=>`<text x="${x(i)+17}" y="197" text-anchor="middle">${escapeHTML(l)}</text>`).join('')}</svg>`;return chartShell(title,subtitle,unit,svg,'waterfall',options)}
function paretoViz(title,subtitle,labels,values,unit,options){const rows=labels.map((l,i)=>({l,v:values[i]})).sort((a,b)=>b.v-a.v),total=values.reduce((a,b)=>a+b,0),max=Math.max(...values)*1.2||1,step=420/Math.max(rows.length-1,1),x=i=>64+i*step,bottom=173,top=28,y=v=>bottom-v/max*(bottom-top),cy=p=>bottom-p/100*(bottom-top);let cumulative=0;rows.forEach(r=>{cumulative+=r.v;r.cum=total?cumulative/total*100:0});const svg=`<svg class="analytics-svg" viewBox="0 0 560 222" data-viz-type="pareto" aria-label="${title}; left axis ${unit}, right axis cumulative percent">${[0,.5,1].map(r=>`<line x1="47" x2="515" y1="${y(max*r)}" y2="${y(max*r)}" class="viz-grid"/><text x="39" y="${y(max*r)+4}" text-anchor="end">${nfmt(max*r)}</text><text x="522" y="${cy(r*100)+4}">${r*100}%</text>`).join('')}${rows.map((r,i)=>`<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,r.l,r.v,unit,{share:total?r.v/total*100:0,cumulative:r.cum})}><rect x="${x(i)-22}" y="${Math.min(y(r.v),bottom-14)}" width="44" height="${Math.max(14,bottom-y(r.v))}" fill="transparent"/><rect x="${x(i)-16}" y="${y(r.v)}" width="32" height="${bottom-y(r.v)}" rx="4" fill="#ffd09d"/></g>`).join('')}<path d="${rows.map((r,i)=>(i?'L':'M')+x(i)+','+cy(r.cum)).join(' ')}" fill="none" stroke="#a0f7da" stroke-width="2.5"/>${rows.map((r,i)=>`<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,r.l,r.v,unit,{share:total?r.v/total*100:0,cumulative:r.cum})}><circle cx="${x(i)}" cy="${cy(r.cum)}" r="12" fill="transparent"/><circle class="viz-dot" cx="${x(i)}" cy="${cy(r.cum)}" r="4" fill="#a0f7da"/></g><text x="${x(i)}" y="200" text-anchor="middle">${escapeHTML(r.l)}</text>`).join('')}<text x="47" y="15">${unit}</text><text x="516" y="15" text-anchor="end">Cumulative share</text></svg>`;return chartShell(title,subtitle,unit,svg,'pareto',options)}
function heatmapViz(title,subtitle,labels,values,unit,options){const target=options.target??100,w=470/Math.max(labels.length,1);const svg=`<svg class="analytics-svg" viewBox="0 0 560 215" data-viz-type="heatmap" aria-label="${title}">${values.map((v,i)=>{const good=v>=target;return `<g class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{target,note:good?'Target achieved':'Below target'})}><rect x="${45+i*w}" y="50" width="${w-8}" height="100" rx="10" fill="${good?'#a0f7da':'#ffd09d'}" fill-opacity="${.16+Math.min(1,v/100)*.25}" stroke="${good?'#a0f7da':'#ffd09d'}" stroke-opacity=".6"/><text x="${45+i*w+(w-8)/2}" y="97" text-anchor="middle" class="heat-value">${nfmt(v)}${unit==='%'?'%':''}</text><text x="${45+i*w+(w-8)/2}" y="129" text-anchor="middle">${escapeHTML(labels[i])}</text></g>`}).join('')}<text x="280" y="184" text-anchor="middle">Target ${target} ${unit} · Mint: achieved · Amber: review</text></svg>`;return chartShell(title,subtitle,unit,svg,'heatmap',{...options,target})}
compositionChart=function(title,subtitle,labels,raw,unit){const values=numericSeries(raw),sum=values.reduce((a,b)=>a+b,0);let offset=0;const id='composition-'+(++vizSequence),arcs=values.map((v,i)=>{const frac=sum?v/sum:0,arc=`<circle class="viz-mark viz-sector" data-viz-index="${i}" ${vizAttrs(title,labels[i],v,unit,{share:frac*100})} cx="95" cy="95" r="66" fill="none" stroke="${palette[i%palette.length]}" stroke-width="23" stroke-dasharray="${frac*414.69} ${414.69-frac*414.69}" stroke-dashoffset="${-offset}" transform="rotate(-90 95 95)"/>`;offset+=frac*414.69;return arc}).join('');return `<section class="panel analytics-panel varied-chart" data-viz-chart="${id}" data-chart-type="donut"><div class="panelhead"><div><h2>${title}</h2><small>${subtitle}</small></div><span class="chart-unit">${unit}</span></div><div class="composition"><svg class="composition-svg" viewBox="0 0 190 190" data-viz-type="donut" aria-label="${title}"><circle cx="95" cy="95" r="66" fill="none" stroke="#ffffff20" stroke-width="23"/>${arcs}<g ${vizAttrs(title,'Total',sum,unit,{share:100})}><circle cx="95" cy="95" r="48" fill="transparent"/><text x="95" y="91" text-anchor="middle" class="composition-total">${nfmt(sum)}</text><text x="95" y="113" text-anchor="middle">${unit} total</text></g></svg><div class="composition-legend">${labels.map((l,i)=>`<button class="viz-mark" data-viz-index="${i}" ${vizAttrs(title,l,values[i],unit,{share:sum?values[i]/sum*100:0})}><span class="legend-dot" style="background:${palette[i%palette.length]}"></span><span>${escapeHTML(l)}</span><strong>${sum?Math.round(values[i]/sum*100):0}%</strong></button>`).join('')}</div></div><div class="chart-caption"><span>Distribution · exact values on hover</span><span>Demo data</span></div></section>`};
bars=function(title,labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],values=[54,70,62,90,84,96,81]){const t=title.toLowerCase();return analyticsChart(title,'Illustrative demo series',labels,values,t.includes('delivery')?'orders':t.includes('downtime')?'hours':t.includes('cost')?'EGP k':'index',{viz:t.includes('supplier')?'line':undefined,type:/trend|performance/.test(t)?'line':'bar'})};
const oldCompactGauge=compactGauge;compactGauge=function(label,value,p,index,color='#a0f7da'){const html=oldCompactGauge(label,value,p,index,color),numeric=parseFloat(String(value).replace(/[^0-9.]/g,''))||0,unit=String(value).includes('%')?'%':String(value).includes('open')?'open cases':'score';return html.replace('<button ',`<button data-viz-point="${escapeHTML(JSON.stringify({title:label,label,value:numeric,unit,note:'Select for KPI details'}))}" `)};
const oldDonut=donut;donut=function(label,p){return oldDonut(label,p).replace('<div class="donut"',`<div ${vizAttrs(label,label,p,'%')} class="donut"`)};
let currentVizElement=null,vizTooltip=null;
function getVizTooltip(){if(vizTooltip)return vizTooltip;vizTooltip=document.createElement('div');vizTooltip.className='viz-tooltip';vizTooltip.id='visualization-tooltip';vizTooltip.setAttribute('role','tooltip');vizTooltip.setAttribute('popover','manual');vizTooltip.hidden=true;document.body.appendChild(vizTooltip);return vizTooltip}
function positionVizTooltip(x,y){const tip=getVizTooltip(),rect=tip.getBoundingClientRect(),width=rect.width||260,height=rect.height||140;tip.style.left=Math.max(8,Math.min(window.innerWidth-width-8,x+16))+'px';tip.style.top=Math.max(8,Math.min(window.innerHeight-height-8,y+16))+'px'}
function showVizTooltip(el,event){if(!el)return;let p;try{p=JSON.parse(el.getAttribute('data-viz-point'))}catch{return}if(currentVizElement!==el)hideVizTooltip();currentVizElement=el;const tip=getVizTooltip();tip.innerHTML=`<div class="viz-tooltip-title"></div><div class="viz-tooltip-label"></div><div class="viz-tooltip-value"></div><div class="viz-tooltip-extra"></div><div class="viz-tooltip-scope"></div>`;tip.querySelector('.viz-tooltip-title').textContent=p.title;tip.querySelector('.viz-tooltip-label').textContent=p.label;tip.querySelector('.viz-tooltip-value').textContent=(typeof p.value==='number'?nfmt(p.value):p.value)+' '+(p.unit||'');const extra=[];if(p.target!==undefined&&p.target!==null)extra.push('Target: '+nfmt(p.target)+' '+p.unit+' · Difference: '+nfmt(Number(p.value)-p.target)+' '+p.unit);if(p.share!==undefined)extra.push('Share of total: '+nfmt(p.share)+'%');if(p.cumulative!==undefined)extra.push('Cumulative share: '+nfmt(p.cumulative)+'%');if(p.note)extra.push(p.note);tip.querySelector('.viz-tooltip-extra').textContent=extra.join('\n');tip.querySelector('.viz-tooltip-scope').textContent=scopeName()+' · '+($('#period').value||'Today')+' · Demo data';tip.hidden=false;try{tip.showPopover?.()}catch{}el.setAttribute('aria-describedby',tip.id);el.classList.add('viz-active');const chart=el.closest('[data-viz-chart]'),index=el.getAttribute('data-viz-index');if(chart&&index!==null)for(const mark of chart.querySelectorAll('.viz-mark'))mark.classList.toggle('viz-muted',mark.getAttribute('data-viz-index')!==index);if(event&&Number.isFinite(event.clientX))positionVizTooltip(event.clientX,event.clientY);else{const r=el.getBoundingClientRect();positionVizTooltip(r.left+r.width/2,r.top+r.height/2)}}
function hideVizTooltip(){if(currentVizElement){currentVizElement.classList.remove('viz-active');currentVizElement.removeAttribute('aria-describedby');const chart=currentVizElement.closest('[data-viz-chart]');if(chart)for(const mark of chart.querySelectorAll('.viz-muted'))mark.classList.remove('viz-muted')}currentVizElement=null;if(vizTooltip){try{vizTooltip.hidePopover?.()}catch{}vizTooltip.hidden=true}}
function enrichVisualizationHovers(){const root=$('#main');if(!root)return;root.querySelectorAll('.compact-panel').forEach((p,i)=>p.setAttribute('data-viz-chart','compact-'+i));root.querySelectorAll('.cip-phases span').forEach((p,i)=>{p.tabIndex=0;p.setAttribute('data-viz-point',JSON.stringify({title:'CIP cycle',label:p.textContent.replace('✓','').trim(),value:i<cipPhase?'Completed':i===cipPhase?'Current phase':'Pending',unit:'',note:'CIP-01 · Cleaning cycle progress'}))});root.querySelectorAll('.compact-gauge').forEach(el=>{{const text=el.querySelector('b')?.textContent||'',label=el.querySelector('small')?.textContent||'KPI';el.setAttribute('data-viz-point',JSON.stringify({title:label,label,value:parseFloat(text)||0,unit:text.includes('%')?'%':text.includes('open')?'open cases':'score'}))}});root.querySelectorAll('.complaint-map button,.sentiment-grid button,.product-ratings button,.delivery-details button').forEach(el=>{const title=el.closest('.compact-panel')?.querySelector('h2')?.textContent||'KPI',value=el.querySelector('strong')?.textContent||'',label=el.querySelector('small')?.textContent||el.querySelector('span')?.textContent||title;el.setAttribute('data-viz-point',JSON.stringify({title,label,value,unit:el.closest('.complaint-map')?'cases':el.closest('.product-ratings')?'/ 5':el.closest('.delivery-details')?'orders':''}))});root.querySelectorAll('.kpis .card').forEach((el,i)=>{const m=pageMetrics()[i];if(m)el.setAttribute('data-viz-point',JSON.stringify({title:m[0],label:m[2],value:m[1],unit:''}))});root.querySelectorAll('.line-progress,.target-track,.bar').forEach(el=>{if(el.closest('[data-viz-point]'))return;const bar=el.matches('.bar,.target-track')?el:el.querySelector('.bar'),fill=bar?.querySelector('i');if(fill){el.tabIndex=0;el.setAttribute('data-viz-point',JSON.stringify({title:el.closest('.pack-line')?'Packaging progress':'Progress',label:el.closest('.pack-line')?.querySelector('.line-select>strong')?.textContent||'Actual progress',value:parseFloat(fill.style.width)||0,unit:'%'}))}});root.querySelectorAll('.plan-list button').forEach((el,i)=>{const nums=(el.querySelector('.row span')?.textContent||'').split('/').map(x=>parseFloat(x.replace(/[^0-9.]/g,'')));el.setAttribute('data-viz-point',JSON.stringify({title:'Output against plan',label:'Line '+(i+1),value:nums[0]||0,unit:'units',target:nums[1],note:'Select to explore the process.'}))});root.querySelectorAll('.stage').forEach(el=>el.setAttribute('data-viz-point',JSON.stringify({title:'Batch journey',label:el.querySelector('strong')?.textContent,value:el.querySelector('b')?.textContent.trim(),unit:'',note:'Select to filter this stage.'})));}
document.addEventListener('pointerover',e=>{const el=e.target.closest?.('[data-viz-point]');if(el&&el!==currentVizElement)showVizTooltip(el,e)});
document.addEventListener('pointermove',e=>{const svg=e.target.closest?.('svg[data-viz-type]');if(svg&&['area','line'].includes(svg.getAttribute('data-viz-type'))){const r=svg.getBoundingClientRect();if(r.width&&r.height){const px=(e.clientX-r.left)/r.width*560,py=(e.clientY-r.top)/r.height*215;if(px>=45&&px<=535&&py>=22&&py<=180){let nearest=null,distance=Infinity;for(const mark of svg.querySelectorAll('.viz-mark')){const dot=mark.querySelector('circle[cx]');if(dot){const d=Math.abs(Number(dot.getAttribute('cx'))-px);if(d<distance){nearest=mark;distance=d}}}if(nearest&&nearest!==currentVizElement)showVizTooltip(nearest,e)}}}if(currentVizElement)positionVizTooltip(e.clientX,e.clientY)});
document.addEventListener('pointerout',e=>{if(currentVizElement&&!currentVizElement.contains(e.relatedTarget))hideVizTooltip()});
document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-viz-point]');if(el)showVizTooltip(el)});
document.addEventListener('focusout',()=>hideVizTooltip());
document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')showVizTooltip(e.target.closest?.('[data-viz-point]'),e)});
document.addEventListener('click',()=>hideVizTooltip());
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideVizTooltip()});
